package com.medipanda.controller;
import com.medipanda.model.*; import com.medipanda.repository.*; import com.medipanda.service.RiderAssignmentService; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/pharmacy")
public class PharmacyController {
 private final OrderRepository orders; private final MedicineRepository medicines; private final PharmacyRepository pharmacies; private final UserRepository users; private final RiderAssignmentService assign; private final com.medipanda.service.NotificationService notifications;
 public PharmacyController(OrderRepository o,MedicineRepository m,PharmacyRepository p,UserRepository u,RiderAssignmentService a,com.medipanda.service.NotificationService n){orders=o;medicines=m;pharmacies=p;users=u;assign=a;notifications=n;}
 @GetMapping("/me") public Pharmacy me(Principal p){return own(p);} @GetMapping("/orders") public List<Order> orders(Principal p){return orders.findByPharmacyIdOrderByCreatedAtDesc(own(p).getId());} @GetMapping("/medicines") public List<Medicine> medicines(Principal p){return medicines.findByPharmacyId(own(p).getId());}
 @PutMapping("/profile") public Pharmacy profile(@RequestBody Pharmacy req,Principal p){Pharmacy x=own(p); if(req.getName()!=null&&!req.getName().isBlank())x.setName(req.getName().trim()); if(req.getArea()!=null)x.setArea(req.getArea().trim()); if(req.getStreet()!=null)x.setStreet(req.getStreet().trim()); if(req.getDescription()!=null)x.setDescription(req.getDescription().trim()); if(req.getImage()!=null&&!req.getImage().isBlank())x.setImage(req.getImage().trim()); return pharmacies.save(x);}
 @PatchMapping("/orders/{id}/ready") public Order ready(@PathVariable String id,Principal p){Pharmacy ph=own(p);Order o=orders.findById(id).orElseThrow();ownOrder(o,ph);if(!Set.of("PENDING","CONFIRMED","PREPARING","READY_FOR_PICKUP","WAITING_FOR_RIDER").contains(o.getStatus()))bad("Order cannot be marked ready now");o.setStatus("READY_FOR_PICKUP");orders.save(o);assign.assignNearest(o);Order saved=orders.findById(o.getId()).orElse(o);if(saved.getCustomerEmail()!=null)users.findByEmailIgnoreCaseOrPhone(saved.getCustomerEmail(),saved.getCustomerEmail()).ifPresent(c->notifications.notifyCustomer(saved,com.medipanda.service.NotificationService.OrderEvent.PACKED));return saved;}
 @PatchMapping("/orders/{id}/status/{status}") public Order status(@PathVariable String id,@PathVariable String status,Principal p){Pharmacy ph=own(p);Order o=orders.findById(id).orElseThrow();ownOrder(o,ph);String s=status.toUpperCase();if(!Set.of("CONFIRMED","PREPARING","CANCELLED").contains(s))bad("Invalid pharmacy status");o.setStatus(s); Order saved=orders.save(o); if(saved.getCustomerEmail()!=null) users.findByEmailIgnoreCaseOrPhone(saved.getCustomerEmail(),saved.getCustomerEmail()).ifPresent(c->notifications.send(c.getId(),"Order updated", "Your order is now "+s.replace("_"," "),"ORDER",saved.getId())); return saved;}
 @PostMapping("/medicines") public Medicine add(@RequestBody Medicine m,Principal p){Pharmacy ph=own(p);m.setId(null);m.setPharmacyId(ph.getId());m.setStock(Math.max(0,m.getStock()));return medicines.save(m);}
 @PutMapping("/medicines/{id}") public Medicine edit(@PathVariable String id,@RequestBody Medicine m,Principal p){Pharmacy ph=own(p);Medicine x=medicines.findById(id).orElseThrow();if(!ph.getId().equals(x.getPharmacyId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Forbidden");x.setName(m.getName());x.setGenericName(m.getGenericName());x.setCategory(m.getCategory());x.setImage(m.getImage());x.setManufacturer(m.getManufacturer());x.setPrice(m.getPrice());x.setOldPrice(m.getOldPrice());x.setStock(Math.max(0,m.getStock()));x.setPrescriptionRequired(m.isPrescriptionRequired());return medicines.save(x);}
 @DeleteMapping("/medicines/{id}") public void delete(@PathVariable String id,Principal p){Pharmacy ph=own(p);Medicine x=medicines.findById(id).orElseThrow();if(!ph.getId().equals(x.getPharmacyId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Forbidden");medicines.deleteById(id);}
 private Pharmacy own(Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();return pharmacies.findByOwnerUserId(u.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"No pharmacy linked to this account"));}
 private void ownOrder(Order o,Pharmacy p){if(!p.getId().equals(o.getPharmacyId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This order does not belong to your pharmacy");} private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
